const ROOT=new URL('./',document.querySelector('script[src$="quick.js"]').src);const main=document.querySelector('#main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=id=>new URL('?viec='+encodeURIComponent(id),ROOT).href;const asset=file=>new URL('assets/'+file,ROOT).href;
function getGuide(id){const t=tutorials.find(x=>x.id===id);if(!t)return null;if(id==='cap-nhat-tien-do'){const report=tutorials.find(x=>x.id==='gui-bao-cao');if(report)return{...t,title:'Cập nhật và gửi báo cáo công việc',description:'Cập nhật 100%, nhập số lượng và gửi báo cáo.',steps:[...t.steps,...report.steps.slice(1)],result:report.result,next:null}}return t}
function groups(steps){const list=[];steps.forEach((s,i)=>{let g=list.at(-1);if(!g||g.image!==s.image||g.steps.length>=3){g={image:s.image,steps:[]};list.push(g)}g.steps.push({...s,n:i+1});if(s.highlight)g.highlight=s.highlight});return list}
function task(t,featured=false){return `<a class="task" href="${link(t.id)}">${featured?'<span class="badge">THƯỜNG DÙNG</span>':''}<strong>${esc(t.title)}</strong><p>${esc(t.description)}</p><span class="label">Xem hướng dẫn</span></a>`}
function home(){const ids=['danh-gia-kpi','cap-nhat-tien-do','dang-ky-cong-viec'];main.innerHTML=`<h1>Anh/Chị cần làm việc gì?</h1><p class="intro">Chọn một việc bên dưới. Xem ảnh và làm theo trên NOTE KPI.</p><div class="featured">${ids.map(getGuide).filter(Boolean).map(t=>task(t,true)).join('')}</div><h2 class="section-label">Công việc cá nhân</h2><div class="task-grid">${tutorials.filter(t=>t.role!=='manager'&&!ids.includes(t.id)&&t.id!=='gui-bao-cao').map(t=>task(t)).join('')}</div><h2 class="section-label manager-label">Dành cho Lãnh đạo / Quản lý</h2><div class="task-grid">${tutorials.filter(t=>t.role==='manager').map(t=>task(t)).join('')}</div><div class="reference-links"><a href="?trang=video">Video hướng dẫn</a><a href="?trang=tai-lieu">Tài liệu PDF</a></div>`;document.title='HDSD NOTE KPI ver 2'}
function guide(t){document.title=t.title+' | NOTE KPI ver 2';main.innerHTML=`<a class="back" href="${ROOT.href}">Chọn việc khác</a><div class="guide-head"><div><h1>${esc(t.title)}</h1><p class="intro">${esc(t.description)}</p></div></div><div class="guide-tools"><a class="button" href="https://notehrm.vn" target="_blank" rel="noopener">Mở NOTE KPI</a><button class="button secondary" data-action="copy" data-link="${esc(link(t.id))}">Sao chép link hướng dẫn</button></div><p class="copy-status" id="copy-status" role="status"></p><div class="notice">Giữ trang này để đối chiếu. Thực hiện các bước dưới đây trên phần mềm NOTE KPI.</div>${groups(t.steps).map(g=>`<section class="group"><div>${g.steps.map(s=>`<div class="step"><h2><span class="number">${s.n}</span><span>${esc(s.title)}</span></h2><p>${esc(s.instruction)}</p>${s.warning?`<p class="inline-note warning"><b>Lưu ý:</b> ${esc(s.warning)}</p>`:''}${s.tip?`<p class="inline-note">${esc(s.tip)}</p>`:''}</div>`).join('')}</div><button class="image-button" data-action="zoom" data-image="${esc(g.image)}" data-highlight="${esc(g.highlight||'')}" aria-label="Phóng to ảnh cho bước ${g.steps[0].n}"><span class="annotated-image"><img src="${asset(g.image)}" alt="Ảnh NOTE: ${esc(g.steps.map(s=>s.title).join('; '))}" loading="lazy">${g.highlight?'<span class="edit-kpi-circle" aria-hidden="true"></span>':''}</span><span class="image-label">Bấm ảnh để xem lớn hơn · Số liệu trong ảnh là ví dụ</span></button></section>`).join('')}<div class="outcome"><strong>Sau khi thực hiện trên NOTE</strong>${esc(t.result)}${t.next&&tutorials.some(x=>x.id===t.next)?`<br><a class="button secondary" href="${link(t.next)}">${t.next==='tra-cong-viec'?'Nếu yêu cầu làm lại: Trả công việc':'Tiếp tục: '+esc(getGuide(t.next).title)}</a>`:''}</div>${t.source?`<p class="source">Tham khảo <a href="${asset(t.source+'.pdf')}#page=${t.page}" target="_blank" rel="noopener">PDF ${t.source==='manager'?'Lãnh đạo':'Chuyên viên'}, trang ${t.page}</a> và quy trình được cung cấp.</p>`:''}`}
function references(page){const vid=page==='video';main.innerHTML=`<a class="back" href="${ROOT.href}">Chọn việc khác</a><h1>${vid?'Video hướng dẫn':'Tài liệu PDF'}</h1><div class="media">${videos.map(v=>`<article><h2>${esc(v.title)}</h2>${vid?`<iframe src="https://www.youtube.com/embed/${encodeURIComponent(v.id)}" title="${esc(v.title)}" loading="lazy" allowfullscreen></iframe><a class="button secondary" href="https://youtu.be/${encodeURIComponent(v.id)}" target="_blank" rel="noopener">Xem trên YouTube</a>`:`<a class="button" href="${asset(v.role+'.pdf')}" target="_blank" rel="noopener">Xem PDF</a><a class="button secondary" href="${asset(v.role+'.pdf')}" download>Tải PDF</a>`}</article>`).join('')}</div>`}
function render(){const p=new URLSearchParams(location.search),id=p.get('viec');if(id){const t=getGuide(id);if(t)guide(t);else main.innerHTML=`<h1>Chưa tìm thấy hướng dẫn này</h1><a class="button" href="${ROOT.href}">Chọn việc cần làm</a>`}else if(['video','tai-lieu'].includes(p.get('trang')))references(p.get('trang'));else home()}
let scale=1;document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b){const a=b.dataset.action;if(a==='zoom'){scale=1;document.querySelector('#zoom-frame').style.width='100%';document.querySelector('#zoom-img').src=asset(b.dataset.image);document.querySelector('#zoom-img').alt=b.getAttribute('aria-label');document.querySelector('#zoom-frame .edit-kpi-circle').hidden=!b.dataset.highlight;document.querySelector('#zoom').showModal()}if(a==='close')document.querySelector('#zoom').close();if(a==='plus'||a==='minus'){scale=Math.min(4,Math.max(.5,scale+(a==='plus'?.25:-.25)));document.querySelector('#zoom-frame').style.width=scale*100+'%'}if(a==='copy'){try{await navigator.clipboard.writeText(b.dataset.link);document.querySelector('#copy-status').textContent='Đã sao chép link. Anh/Chị có thể dán vào tin nhắn.'}catch{const status=document.querySelector('#copy-status');status.innerHTML=`<label class="copy-fallback">Sao chép đường dẫn này:<input readonly value="${esc(b.dataset.link)}"></label>`;status.querySelector('input').select()}}return}const a=e.target.closest('a');if(!a||a.target||a.hasAttribute('download')||e.ctrlKey||e.metaKey||e.shiftKey)return;const u=new URL(a.href);if(u.origin===ROOT.origin&&u.pathname===ROOT.pathname){e.preventDefault();history.pushState(null,'',u.href);render();window.scrollTo(0,0)}});window.addEventListener('popstate',render);render();
